CREATE TABLE `usage_events` (`id` integer PRIMARY KEY AUTOINCREMENT,`event_key` text,`api_group_key` text,`provider` text,`endpoint` text,`auth_type` text,`request_id` text,`session_id` text,`parent_session_id` text,`client_ip` text,`x_forwarded_for` text,`user_agent` text,`model` text,`model_alias` text,`response_model` text NOT NULL DEFAULT "",`reasoning_effort` text NOT NULL DEFAULT "",`service_tier` text NOT NULL DEFAULT "",`response_service_tier` text NOT NULL DEFAULT "",`executor_type` text NOT NULL DEFAULT "",`timestamp` datetime,`source` text,`auth_index` text,`failed` numeric,`status_code` integer,`generate` numeric NOT NULL DEFAULT true,`stream` numeric,`latency_ms` integer,`ttft_ms` integer,`input_tokens` integer,`output_tokens` integer,`reasoning_tokens` integer,`cached_tokens` integer,`cache_read_tokens` integer NOT NULL DEFAULT 0,`cache_creation_tokens` integer NOT NULL DEFAULT 0,`total_tokens` integer,`created_at` datetime);
CREATE INDEX `idx_usage_events_auth_index` ON `usage_events`(`auth_index`);
CREATE INDEX `idx_usage_events_model` ON `usage_events`(`model`);
CREATE INDEX `idx_usage_events_api_group_key_timestamp` ON `usage_events`(`api_group_key`,`timestamp`);
CREATE INDEX `idx_usage_events_auth_index_timestamp_id` ON `usage_events`(`auth_index`,`timestamp`,`id`);
CREATE INDEX `idx_usage_events_auth_type_auth_index_id` ON `usage_events`(`auth_type`,`auth_index`,`id`);
CREATE INDEX `idx_usage_events_timestamp_id` ON `usage_events`(`timestamp` desc,`id` desc);
CREATE TABLE `error_events` (`id` integer PRIMARY KEY AUTOINCREMENT,`timestamp` datetime,`received_at` datetime,`provider` text,`model` text,`auth_id` text,`auth_index` text,`status_code` integer,`body` text,`code` text,`retryable` numeric,`auth_status` text,`auth_status_message` text,`auth_disabled` numeric,`auth_unavailable` numeric,`auth_next_retry_after` datetime,`auth_quota_exceeded` numeric,`auth_quota_reason` text,`auth_quota_next_recover_at` datetime,`auth_quota_backoff_level` integer,`auth_model_name` text,`auth_model_status` text,`auth_model_status_message` text,`auth_model_unavailable` numeric,`auth_model_next_retry_after` datetime,`auth_model_quota_exceeded` numeric,`auth_model_quota_reason` text,`auth_model_quota_next_recover_at` datetime,`auth_model_quota_backoff_level` integer);
CREATE INDEX `idx_error_events_auth_index_timestamp_id` ON `error_events`(`auth_index`,`timestamp` desc,`id` desc);
CREATE TABLE `usage_identities` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`alias` text,`auth_type` integer,`auth_type_name` text,`identity` text,`type` text,`provider` text,`lookup_key` text,`prefix` text,`base_url` text,`file_name` text,`file_path` text,`priority` integer,`disabled` numeric,`note` text,`account_id` text,`project_id` text,`xai_user_id` text,`active_start` datetime,`active_until` datetime,`plan_type` text,`total_requests` integer,`success_count` integer,`failure_count` integer,`input_tokens` integer,`output_tokens` integer,`reasoning_tokens` integer,`cached_tokens` integer,`cache_read_tokens` integer NOT NULL DEFAULT 0,`total_tokens` integer,`stats_reset_at` datetime,`reset_total_requests` integer NOT NULL DEFAULT 0,`reset_success_count` integer NOT NULL DEFAULT 0,`reset_failure_count` integer NOT NULL DEFAULT 0,`reset_input_tokens` integer NOT NULL DEFAULT 0,`reset_cache_read_tokens` integer NOT NULL DEFAULT 0,`reset_total_tokens` integer NOT NULL DEFAULT 0,`last_aggregated_usage_event_id` integer,`first_used_at` datetime,`last_used_at` datetime,`stats_updated_at` datetime,`is_deleted` numeric,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime);
CREATE INDEX `idx_usage_identities_auth_type_type` ON `usage_identities`(`auth_type`,`type`);
CREATE UNIQUE INDEX `uniq_usage_identities_type_identity` ON `usage_identities`(`auth_type`,`identity`);
CREATE INDEX `idx_usage_identities_auth_type_name_id` ON `usage_identities`(`auth_type`,`name`,`id`);
